//! Canonical BUTTON type/value and native state transactions.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form method=post action='/submit'><input id=edit name=q value=Seed><button id=area name=go type=button value=initial>Caption</button><input id=neighbor value=neighbor></form></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://button-type-value.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn button_type_value_canonical_descriptors_and_once_conversion(){for key in ["type","value"]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!(r#"var key='{key}',x=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLButtonElement.prototype,key);if(!a||!a.enumerable||!a.configurable||a.get.name!=='get '+key||a.set.name!=='set '+key||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,key))throw 'canonical BUTTON';var calls=0;x[key]={{toString:function(){{calls++;return 'ReSeT';}},valueOf:function(){{throw 'wrong hint';}}}};if(calls!==1||x[key]!==(key==='type'?'reset':'ReSeT')||x.getAttributeNS(null,key)!=='ReSeT'||x.textContent!=='Caption')throw 'BUTTON conversion';"#));}}
#[test]
fn button_type_value_native_inert_exact_namespace_and_raw_backing(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),owner=new Document(),inert=owner.createElementNS('http://www.w3.org/1999/xhtml','button');for(var target of [x,inert]){target.removeAttribute('type');target.removeAttribute('value');target.setAttributeNS('urn:other','type','reset');target.setAttributeNS(null,'TYPE','reset');target.setAttributeNS('urn:other','value','foreign');target.setAttributeNS(null,'VALUE','upper');if(target.type!=='submit'||target.value!=='')throw 'namespace alias';target.type='ReSeT';target.value='raw\ud800x\udc00';if(target.type!=='reset'||target.getAttributeNS(null,'type')!=='ReSeT'||target.value!=='raw\ud800x\udc00'||target.getAttributeNS(null,'value')!==target.value||target.getAttributeNS('urn:other','type')!=='reset'||target.getAttributeNS(null,'TYPE')!=='reset'||target.getAttributeNS('urn:other','value')!=='foreign'||target.getAttributeNS(null,'VALUE')!=='upper')throw 'exact BUTTON metadata';}"#);}

#[test]
fn button_type_value_type_states_auto_contexts_and_inert_parent_changes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),owner=new Document(),inert=owner.createElementNS('http://www.w3.org/1999/xhtml','button');for(var target of [x,inert]){for(var pair of [['submit','submit'],['ReSeT','reset'],['BuTtOn','button'],['','submit'],['invalid','submit'],[' reset ','submit'],['auto','submit'],['re\ud800set','submit']]){target.type=pair[0];if(target.type!==pair[1]||target.getAttributeNS(null,'type')!==pair[0])throw 'type state';}}var select=owner.createElementNS('http://www.w3.org/1999/xhtml','select');select.appendChild(inert);if(inert.type!=='button')throw 'inert Auto select parent';inert.type='submit';if(inert.type!=='submit')throw 'explicit submit parent';inert.removeAttribute('type');select.removeChild(inert);inert.setAttribute('command','--custom');if(inert.type!=='button')throw 'Auto command';inert.type='RESET';if(inert.type!=='reset')throw 'explicit reset command';inert.removeAttribute('type');inert.removeAttribute('command');inert.setAttributeNS('urn:other','command','--foreign');if(inert.type!=='submit')throw 'foreign command alias';inert.setAttributeNS(null,'commandfor','target');if(inert.type!=='button')throw 'Auto commandfor';"#);}
#[test]
fn button_type_value_attribute_producers_keep_identity_observers_and_native_state(){for key in ["type","value"]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var key='{key}',x=document.getElementById('area'),attribute=x.getAttributeNodeNS(null,key),watch=new MutationObserver(function(){{}});watch.observe(x,{{attributes:true,attributeOldValue:true,attributeFilter:[key]}});document.getElementById('edit').value='dirty';"));let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();for source in ["x.setAttribute(key,'ReSeT');","x.setAttributeNS(null,key,'ReSeT');","attribute.value='ReSeT';","attribute.nodeValue='ReSeT';","attribute.textContent='ReSeT';"]{p.begin_job();run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x[key]!==(key==='type'?'reset':'ReSeT')||x.getAttributeNodeNS(null,key)!==attribute||records.length!==1||records[0].attributeName!==key||x.textContent!=='Caption'||document.getElementById('edit').value!=='dirty')throw 'BUTTON producer';");let c=&f.controls[&n];if key=="type"{assert_eq!(c.kind,forms::Kind::Reset);assert_eq!(c.value.text(),"initial");}else{assert_eq!(c.kind,forms::Kind::Button);assert_eq!(c.value.text(),"ReSeT");}}run(&mut d,&mut f,&mut p,"var replacement=document.createAttribute(key);replacement.value='submit';x.setAttributeNodeNS(replacement);if(attribute.ownerElement!==null||replacement.ownerElement!==x||x[key]!=='submit')throw 'BUTTON replacement';");}}
#[test]
fn button_type_value_once_reentrancy_abrupt_conversion_and_saved_authority(){for key in ["type","value"]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!(r#"var key='{key}',x=document.getElementById('area'),P=HTMLButtonElement.prototype,a=Object.getOwnPropertyDescriptor(P,key),calls=0;for(var bad of [{{}},document,document.createElement('input'),Object.create(P)]){{try{{a.set.call(bad,{{toString:function(){{calls++;return 'reset';}}}});throw 'brand missing';}}catch(e){{if(!(e instanceof TypeError))throw e;}}}}if(calls)throw 'brand converted';x[key]={{toString:function(){{calls++;x[key]='button';return 'reset';}}}};if(calls!==1||x[key]!=='reset')throw 'reentrant';var marker={{}};try{{x[key]={{toString:function(){{calls++;x.setAttribute('data-side','kept');throw marker;}}}};throw 'missing abrupt';}}catch(e){{if(e!==marker)throw e;}}try{{x[key]=Symbol('bad');throw 'missing Symbol refusal';}}catch(e){{if(!(e instanceof TypeError))throw e;}}if(calls!==2||x[key]!=='reset'||x.getAttribute('data-side')!=='kept')throw 'abrupt effects';Object.defineProperty(P,key,{{get:function(){{return 'author';}},set:function(v){{this.setAttribute('data-author',v);}},configurable:true}});x[key]='override';a.set.call(x,'submit');if(x[key]!=='author'||a.get.call(x)!=='submit'||x.getAttribute('data-author')!=='override')throw 'saved authority';delete P[key];if(x[key]!==undefined)throw 'deleted hidden member';Object.defineProperty(P,key,a);var C=HTMLButtonElement;delete window.HTMLButtonElement;if(!(x instanceof C)||a.get.call(x)!=='submit')throw 'saved roots';"#));}}
#[test]
fn button_type_value_actual_submitter_post_and_reset_preserve_caption(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area');x.value='a\ud800b';x.type='SuBmIt';document.getElementById('edit').value='edited';if(x.value!=='a\ud800b'||x.type!=='submit'||x.textContent!=='Caption')throw 'submit metadata';"#);let owner=(0..d.nodes.len()).find(|n|d.attr(*n,"id")==Some("form")).unwrap();let button=(0..d.nodes.len()).find(|n|d.attr(*n,"id")==Some("area")).unwrap();let l=crate::navigation::address("https://button-type-value.test/source",&crate::navigation::Location::home()).unwrap();for(submitter,expected)in[(Some(button),"q=edited&go=a%EF%BF%BDb"),(None,"q=edited")]{let s=f.submit_request(&d,owner,submitter,&l,&l).unwrap();let crate::http::Request::FormPost{body,..}=s.request else{panic!("POST")};assert_eq!(String::from_utf8(body).unwrap(),expected);}run(&mut d,&mut f,&mut p,"x.type='ReSeT';");f.reset_in_document(&d,owner).unwrap();run(&mut d,&mut f,&mut p,r#"if(x.type!=='reset'||x.value!=='a\ud800b'||x.textContent!=='Caption'||document.getElementById('edit').value!=='Seed')throw 'reset isolation';"#);assert_eq!(f.controls[&button].kind,forms::Kind::Reset);}
#[test]
fn button_type_value_resource_refusal_and_fresh_recovery(){for key in ["type","value"]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var key='{key}',x=document.getElementById('area');document.getElementById('edit').value='dirty';"));let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("BUTTON")};let nodes=format!("{:?}",d.nodes);let capture=|f:&Forms|f.controls.iter().map(|(n,c)|(*n,c.kind,c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value)).collect::<Vec<_>>();let before=capture(&f);let accounting=(p.state.retained,p.state.dom_commits);let retained=p.state.retained_limit;p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let value=Value::String("growing".repeat(64));let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if key=="type"{bridge.button_type_set(object,&value)}else{bridge.button_value_set(object,&value)};assert!(result.is_err());assert_eq!(format!("{:?}",d.nodes),nodes);assert_eq!(capture(&f),before);assert_eq!((p.state.retained,p.state.dom_commits),accounting);p.state.retained_limit=retained;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x[key]='reset';if(x[key]!=='reset'||document.getElementById('edit').value!=='dirty')throw 'BUTTON recovery';");}}}
#[test]
fn button_type_value_saved_child_origin_refuses_before_conversion(){for key in ["type","value"]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var key='{key}',x=document.getElementById('area'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLButtonElement.prototype,key),calls=0;a.set.call(x,'reset');if(a.get.call(x)!=='reset')throw 'same origin';"));p.set_location(&crate::navigation::address("https://foreign-button-type-value.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);p.begin_job();let e=p.runtime.execute("a.set.call(x,{toString:function(){calls++;return 'submit';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);p.set_location(&crate::navigation::address("https://button-type-value.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||x[key]!=='reset')throw 'origin conversion';a.set.call(x,'submit');if(a.get.call(x)!=='submit')throw 'origin recovery';");}}
